CREATE TABLE session_preparation_jobs(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,project_id TEXT NOT NULL,session_id TEXT NOT NULL,entry INTEGER NOT NULL CHECK(entry BETWEEN 1 AND 25),state TEXT NOT NULL CHECK(state IN ('queued','running','prepared','failed','cancelled')),attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 3),not_before TEXT NOT NULL,next_attempt_at TEXT NOT NULL,lease_token TEXT,lease_until TEXT,control_revision INTEGER,preparation_id TEXT,payload TEXT CHECK(payload IS NULL OR (json_valid(payload) AND length(payload)<=196608)),last_error TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,CHECK((state='running')=(lease_token IS NOT NULL AND lease_until IS NOT NULL)),CHECK((state='prepared')=(preparation_id IS NOT NULL AND payload IS NOT NULL)));
--> statement-breakpoint
CREATE INDEX session_preparation_jobs_due ON session_preparation_jobs(state,next_attempt_at,not_before);
--> statement-breakpoint
CREATE INDEX session_preparation_jobs_owner ON session_preparation_jobs(owner_id,project_id,session_id);
--> statement-breakpoint
CREATE UNIQUE INDEX session_preparation_jobs_live_entry ON session_preparation_jobs(owner_id,session_id,entry) WHERE state IN ('queued','running');
--> statement-breakpoint
CREATE TABLE session_preparation_job_events(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,owner_id TEXT NOT NULL,project_id TEXT NOT NULL,session_id TEXT NOT NULL,job_id TEXT NOT NULL,document TEXT NOT NULL CHECK(json_valid(document)),created_at TEXT NOT NULL);
--> statement-breakpoint
CREATE INDEX session_preparation_job_events_scope ON session_preparation_job_events(owner_id,project_id,session_id,sequence DESC);
--> statement-breakpoint
CREATE TRIGGER session_preparation_job_keep BEFORE DELETE ON session_preparation_jobs BEGIN SELECT RAISE(ABORT,'Preparation jobs are retained'); END;
--> statement-breakpoint
CREATE TRIGGER session_preparation_job_identity BEFORE UPDATE ON session_preparation_jobs WHEN NEW.id<>OLD.id OR NEW.owner_id<>OLD.owner_id OR NEW.project_id<>OLD.project_id OR NEW.session_id<>OLD.session_id OR NEW.entry<>OLD.entry OR NEW.not_before<>OLD.not_before OR NEW.created_at<>OLD.created_at OR OLD.state IN ('prepared','failed','cancelled') OR NEW.attempts<OLD.attempts OR NEW.attempts>OLD.attempts+1 OR julianday(NEW.updated_at)<julianday(OLD.updated_at) BEGIN SELECT RAISE(ABORT,'Preparation job context differs'); END;
--> statement-breakpoint
CREATE TRIGGER session_preparation_job_claim BEFORE UPDATE ON session_preparation_jobs WHEN NEW.state='running' BEGIN SELECT CASE WHEN (OLD.state<>'queued' AND NOT(OLD.state='running' AND julianday(OLD.lease_until)<=julianday('now'))) OR julianday(NEW.lease_until)<=julianday('now') OR julianday(NEW.lease_until)>julianday('now','+60 seconds') OR NEW.attempts<>OLD.attempts+1 OR julianday(NEW.not_before)>julianday('now') OR julianday(NEW.next_attempt_at)>julianday('now') OR NOT EXISTS(SELECT 1 FROM imported_trade_sessions s JOIN imported_trade_session_controls c ON c.owner_id=s.owner_id AND c.session_id=s.id WHERE s.owner_id=NEW.owner_id AND s.project_id=NEW.project_id AND s.id=NEW.session_id AND s.state='active' AND c.state='ready' AND c.revision=NEW.control_revision) OR EXISTS(SELECT 1 FROM session_preparation_jobs j WHERE j.owner_id=NEW.owner_id AND j.id<>NEW.id AND j.state='running' AND julianday(j.lease_until)>julianday('now')) THEN RAISE(ABORT,'Preparation job not eligible') END; END;
--> statement-breakpoint
CREATE TRIGGER session_preparation_job_result BEFORE UPDATE ON session_preparation_jobs WHEN NEW.state='prepared' BEGIN SELECT CASE WHEN json_extract(NEW.payload,'$.history.id') IS NOT NEW.preparation_id OR json_extract(NEW.payload,'$.history.document.session.sessionId') IS NOT NEW.session_id OR json_extract(NEW.payload,'$.history.document.session.entry') IS NOT NEW.entry OR json_extract(NEW.payload,'$.order.executionAllowed') IS NOT 0 OR OLD.state<>'running' OR julianday(OLD.lease_until)<=julianday('now') OR NOT EXISTS(SELECT 1 FROM imported_swap_preparations p JOIN imported_trade_session_controls c ON c.owner_id=p.owner_id AND c.session_id=NEW.session_id JOIN imported_trade_sessions s ON s.owner_id=c.owner_id AND s.id=c.session_id WHERE p.owner_id=NEW.owner_id AND p.project_id=NEW.project_id AND p.id=NEW.preparation_id AND p.document=json_extract(NEW.payload,'$.history.document') AND json_extract(p.document,'$.transaction.sha256')=json_extract(NEW.payload,'$.order.preparation.sha256') AND p.wallet_address=json_extract(NEW.payload,'$.order.preparation.wallet') AND json_extract(p.document,'$.session.sessionId')=NEW.session_id AND json_extract(p.document,'$.session.entry')=NEW.entry AND c.state='ready' AND c.revision=OLD.control_revision AND s.state='active') THEN RAISE(ABORT,'Preparation job result differs') END; END;
--> statement-breakpoint
CREATE TRIGGER session_preparation_job_event_insert AFTER INSERT ON session_preparation_jobs BEGIN INSERT INTO session_preparation_job_events(id,owner_id,project_id,session_id,job_id,document,created_at) VALUES(lower(hex(randomblob(16))),NEW.owner_id,NEW.project_id,NEW.session_id,NEW.id,json_object('id',NEW.id,'entry',NEW.entry,'state',NEW.state,'attempts',NEW.attempts,'preparationId',NEW.preparation_id,'error',NEW.last_error),NEW.updated_at); END;
--> statement-breakpoint
CREATE TRIGGER session_preparation_job_event_update AFTER UPDATE ON session_preparation_jobs BEGIN INSERT INTO session_preparation_job_events(id,owner_id,project_id,session_id,job_id,document,created_at) VALUES(lower(hex(randomblob(16))),NEW.owner_id,NEW.project_id,NEW.session_id,NEW.id,json_object('id',NEW.id,'entry',NEW.entry,'state',NEW.state,'attempts',NEW.attempts,'preparationId',NEW.preparation_id,'error',NEW.last_error),NEW.updated_at); END;
--> statement-breakpoint
CREATE TRIGGER session_preparation_job_event_keep BEFORE DELETE ON session_preparation_job_events BEGIN SELECT RAISE(ABORT,'Preparation job events are retained'); END;
--> statement-breakpoint
CREATE TRIGGER session_preparation_job_event_immutable BEFORE UPDATE ON session_preparation_job_events BEGIN SELECT RAISE(ABORT,'Preparation job events are immutable'); END;
--> statement-breakpoint
CREATE TRIGGER session_preparation_job_admission BEFORE INSERT ON session_preparation_jobs BEGIN SELECT CASE WHEN NEW.state<>'queued' OR NEW.attempts<>0 OR NEW.payload IS NOT NULL OR NEW.lease_token IS NOT NULL OR NEW.preparation_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM imported_trade_sessions s JOIN imported_trade_session_controls c ON c.owner_id=s.owner_id AND c.session_id=s.id JOIN imported_token_projects p ON p.owner_id=s.owner_id AND p.id=s.project_id JOIN workspace_wallets w ON w.owner_id=s.owner_id AND w.chain='Solana' AND w.address=json_extract(s.document,'$.entries['||(NEW.entry-1)||'].wallet') WHERE s.owner_id=NEW.owner_id AND s.id=NEW.session_id AND s.project_id=NEW.project_id AND s.state='active' AND c.state='ready' AND p.archived=0 AND p.revision=json_extract(s.document,'$.projectRevision') AND w.archived=0 AND w.revision=json_extract(s.document,'$.entries['||(NEW.entry-1)||'].walletRevision') AND json_extract(s.document,'$.entries['||(NEW.entry-1)||'].entry')=NEW.entry AND (json_type(s.document,'$.schedule') IS NULL OR ABS(julianday(NEW.not_before)-(julianday(json_extract(s.document,'$.schedule.startAt'))+(NEW.entry-1)*json_extract(s.document,'$.schedule.spacingSeconds')/86400.0))<0.00000001)) THEN RAISE(ABORT,'Preparation job admission differs') END; END;
